65	                return rawValueToSessionHeadersValue();
66	            }
67	            return rawValueToHeadersValue();
68	        } else if (isTimestamped(store) && !isVersioned(store)) {
69	            // should not prepend timestamp when restoring records for versioned store, as
70	            // timestamp is used separately during put() process for restore of versioned stores
71	            return rawValueToTimestampedValue();
72	        }
73	
74	        // If top-level check didn't find the type, unwrap to find adapters
75	        // This handles persistent stores that use adapters
76	        StateStore current = store;
77	        while (current != null) {
78	            if (current instanceof TimestampedToHeadersStoreAdapter || current instanceof TimestampedToHeadersWindowStoreAdapter) {
79	                // Adapter wraps a timestamped store, so restore in timestamped format
80	                return rawValueToTimestampedValue();
81	            } else if (current instanceof PlainToHeadersStoreAdapter || current instanceof PlainToHeadersWindowStoreAdapter) {
82	                // Adapter wraps a plain store, so restore in plain format
83	                return identity();
