468	    private Optional<OffsetAndMetadata> findOffsetAndMetadata(final TopicPartition partition) {
469	        Long offset = partitionGroup.headRecordOffset(partition);
470	        Optional<Integer> leaderEpoch = partitionGroup.headRecordLeaderEpoch(partition);
471	        final long partitionTime = partitionGroup.partitionTimestamp(partition);
472	        if (offset == null) {
473	            final OffsetAndMetadata offsetAndMetadata = nextOffsetsAndMetadataToBeConsumed.get(partition);
474	            if (offsetAndMetadata == null) {
475	                // it may be that we have not yet consumed any record from this partition, hence nothing to commit
476	                return Optional.empty();
477	            }
478	            offset = offsetAndMetadata.offset();
479	            leaderEpoch = offsetAndMetadata.leaderEpoch();
480	        }
481	        return Optional.of(new OffsetAndMetadata(offset,
482	                leaderEpoch,
483	                new TopicPartitionMetadata(partitionTime, processorContext.processorMetadata()).encode()));
484	    }
